spec_raw:
{
  "cleaner": {
    "params": {
      "drop_if_constant": {
        "choice": [false, true]
      }
    }
  },
  "vectorizer": {
    "params": {
      "cardinality_threshold": {
        "int": [10, 50]
      }
    },
    "slots": {
      "high_cardinality": [
        "skrub.MinHashEncoder",
        "skrub.GapEncoder"
      ],
      "low_cardinality": [
        "sklearn.preprocessing.OneHotEncoder"
      ]
    }
  },
  "scoped_encodings": [
    {
      "name": "missing_flags",
      "cols": [
        "Name_of_Associated_Covered_Device_or_Medical_Supply1",
        "Name_of_Associated_Covered_Drug_or_Biological1"
      ],
      "options": [
        "skip",
        {
          "name": "sklearn.impute.SimpleImputer",
          "params": {
            "strategy": {
              "choice": ["constant"]
            },
            "fill_value": {
              "choice": ["__MISSING__"]
            },
            "add_indicator": {
              "choice": [true]
            }
          }
        }
      ],
      "position": "pre_encode",
      "additive": true
    },
    {
      "name": "specialty_encoder",
      "cols": [
        "Physician_Specialty"
      ],
      "options": [
        "skip",
        {
          "name": "skrub.MinHashEncoder",
          "params": {
            "n_components": {
              "int": [10, 30]
            }
          }
        }
      ],
      "position": "pre_encode",
      "additive": false
    }
  ],
  "stages": [
    {
      "name": "scale",
      "options": [
        "skip",
        "sklearn.preprocessing.StandardScaler"
      ]
    },
    {
      "name": "feature_eng",
      "options": [
        "skip"
      ]
    }
  ],
  "model": [
    {
      "name": "lightgbm.LGBMClassifier",
      "prior": 0.8,
      "params": {
        "n_estimators": {
          "int": [100, 500]
        },
        "learning_rate": {
          "float": [0.01, 0.3],
          "log": true
        },
        "max_depth": {
          "int": [3, 12]
        },
        "scale_pos_weight": {
          "float": [1.0, 20.0]
        },
        "colsample_bytree": {
          "float": [0.5, 1.0]
        }
      }
    },
    {
      "name": "xgboost.XGBClassifier",
      "prior": 0.7,
      "params": {
        "n_estimators": {
          "int": [100, 500]
        },
        "learning_rate": {
          "float": [0.01, 0.3],
          "log": true
        },
        "max_depth": {
          "int": [3, 12]
        },
        "scale_pos_weight": {
          "float": [1.0, 20.0]
        },
        "subsample": {
          "float": [0.5, 1.0]
        }
      }
    },
    {
      "name": "sklearn.ensemble.HistGradientBoostingClassifier",
      "prior": 0.6,
      "params": {
        "learning_rate": {
          "float": [0.01, 0.3],
          "log": true
        },
        "max_iter": {
          "int": [100, 600]
        },
        "max_depth": {
          "int": [2, 16]
        },
        "class_weight": {
          "choice": ["balanced", null]
        }
      }
    },
    {
      "name": "sklearn.linear_model.LogisticRegression",
      "prior": 0.3,
      "params": {
        "C": {
          "float": [0.001, 1000.0],
          "log": true
        },
        "class_weight": {
          "choice": ["balanced", null]
        },
        "max_iter": {
          "int": [100, 1000]
        }
      }
    }
  ]
}
